-- Tenancy N7 (PR 3): a container, its members and their key material are in one org. Handlers
-- check the org first and answer as for a missing row; these triggers are only the backstop.
CREATE TRIGGER memberships_org_match BEFORE INSERT ON memberships WHEN (SELECT org_id FROM users WHERE id=NEW.user_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
CREATE TRIGGER memberships_org_match_move BEFORE UPDATE OF user_id,container_id ON memberships WHEN (SELECT org_id FROM users WHERE id=NEW.user_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
CREATE TRIGGER invitations_org_match BEFORE UPDATE OF status ON invitations WHEN NEW.status='accepted' AND (SELECT org_id FROM users WHERE id=NEW.invitee_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
CREATE TRIGGER key_envelopes_org_match BEFORE INSERT ON key_envelopes WHEN (SELECT u.org_id FROM devices d JOIN users u ON u.id=d.user_id WHERE d.id=NEW.device_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
CREATE TRIGGER key_envelopes_org_match_move BEFORE UPDATE OF device_id,container_id ON key_envelopes WHEN (SELECT u.org_id FROM devices d JOIN users u ON u.id=d.user_id WHERE d.id=NEW.device_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
CREATE TRIGGER device_containers_org_match BEFORE INSERT ON device_containers WHEN (SELECT u.org_id FROM devices d JOIN users u ON u.id=d.user_id WHERE d.id=NEW.device_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
CREATE TRIGGER device_containers_org_match_move BEFORE UPDATE OF device_id,container_id ON device_containers WHEN (SELECT u.org_id FROM devices d JOIN users u ON u.id=d.user_id WHERE d.id=NEW.device_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
CREATE TRIGGER invitation_envelopes_org_match BEFORE INSERT ON invitation_envelopes WHEN (SELECT u.org_id FROM devices d JOIN users u ON u.id=d.user_id WHERE d.id=NEW.device_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
CREATE TRIGGER invitation_envelopes_org_match_move BEFORE UPDATE OF device_id,container_id ON invitation_envelopes WHEN (SELECT u.org_id FROM devices d JOIN users u ON u.id=d.user_id WHERE d.id=NEW.device_id) <> (SELECT org_id FROM containers WHERE id=NEW.container_id) BEGIN SELECT RAISE(ABORT,'member in another org'); END;
